  name: '',
  value: '',
  stage: 'lead',
  companyId: '',
  contactId: null,
  expectedCloseDate: '',
};

function parseDateValue(value) {
  if (!value) {
    return '';
  }

  return value.slice(0, 10);
}

export function DealFormDialog({
  initialValues,
