  const contactsQuery = useContactList({
    page: 1,
    pageSize: 100,
    companyId: values.companyId || undefined,
  });

  const companyOptions = useMemo(
    () => companiesQuery.data?.items ?? [],
    [companiesQuery.data?.items],
  );
  const selectedCompany = useMemo(
    () =>
      companyOptions.find((company) => company.id === values.companyId) ??
      (values.companyId
        ? {
            id: values.companyId,
            name: initialValues?.company?.name || values.companyId,
          }
        : null),
    [companyOptions, initialValues?.company?.name, values.companyId],
  );

  const contactOptions = useMemo(
    () => (values.companyId ? contactsQuery.data?.items ?? [] : []),
    [contactsQuery.data?.items, values.companyId],
  );
  const selectedContact = useMemo(
    () =>
      contactOptions.find((contact) => contact.id === values.contactId) ??
      (values.contactId
        ? {
            id: values.contactId,
            name: values.contactId,
          }
        : null),
    [contactOptions, values.contactId],
  );

  const numericValue = Number(values.value);

  const errors = {
    name: !values.name?.trim() ? 'Name is required.' : '',
    value:
      values.value === '' || Number.isNaN(numericValue)
        ? 'Value is required.'
        : numericValue < 0
          ? 'Value must be non-negative.'
