  const isFormValid = !errors.name && !errors.value && !errors.companyId;

  useEffect(() => {
    if (!open) {
      return;
    }

    setValues({
      ...emptyValues,
      ...initialValues,
      value:
        initialValues?.value === undefined || initialValues?.value === null
          ? ''
          : String(initialValues.value),
      stage: initialValues?.stage || 'lead',
      contactId: initialValues?.contactId ?? null,
      expectedCloseDate: parseDateValue(initialValues?.expectedCloseDate),
    });
    setTouched({ name: false, value: false, companyId: false });
  }, [initialValues, open]);

  const handleChange = (field) => (event) => {
    setValues((current) => ({
      ...current,
      [field]: event.target.value,
    }));
  };

  const handleBlur = (field) => () => {
    setTouched((current) => ({
      ...current,
      [field]: true,
    }));
  };

  const handleCompanyChange = (_, company) => {
