import {
  Autocomplete,
  Button,
  CircularProgress,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Stack,
  TextField,
} from '@mui/material';
import { useEffect, useState } from 'react';
import { formatForDatetimeLocal } from 'utils/formatDate';
import { useCompanyList } from '../companies/companyQueries';


const emptyValues = {
  companyId: '',
  name: '',
  email: '',
  phone: '',
  role: '',
  lastContactedAt: '',
};


export function ContactFormDialog({
  initialValues,
  isPending,
  mode,
  onClose,
  onSubmit,
  open,
}) {
  const [values, setValues] = useState(emptyValues);
  const [touched, setTouched] = useState({
    companyId: false,
    name: false,
    email: false,
    phone: false,
  });
  const companiesQuery = useCompanyList({ page: 1, pageSize: 100 });
  const companyOptions = companiesQuery.data?.items ?? [];
  const selectedCompany = companyOptions.find(
    (company) => company.id === values.companyId,
  ) ?? null;

  const phoneDigits = values.phone?.replace(/[^0-9]/g, '') || '';

  // 校验逻辑：只针对姓名、邮箱、手机号三项必填项
  const errors = {
    companyId: !values.companyId ? 'Company is required.' : '',
    name: !values.name?.trim() ? 'Name is required.' : '',
    email: !values.email?.trim()
      ? 'Email is required.'
      : !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(values.email)
        ? 'Invalid email format.'
        : '',
    phone: !values.phone?.trim()
      ? 'Phone is required.'
      : !values.phone.trim().startsWith('+')
        ? 'Must start with "+" and country code (e.g., +86).'
        : phoneDigits.length < 8 || phoneDigits.length > 15
          ? 'Invalid phone number length (8-15 digits required).'
          : '',
  };

          const isFormValid =
            !errors.companyId && !errors.name && !errors.email && !errors.phone;

  useEffect(() => {
    if (!open) {
      return;
    }

    setValues({
      ...emptyValues,
      ...initialValues,
      lastContactedAt: formatForDatetimeLocal(initialValues?.lastContactedAt),
    });
    setTouched({ companyId: false, name: false, email: false, phone: false });
  }, [initialValues, open]);

  const handleChange = (field) => (event) => {
    setValues((current) => ({ ...current, [field]: event.target.value }));
  };

  const handleBlur = (field) => () => {
    setTouched((current) => ({ ...current, [field]: true }));
  };

  const handleCompanyChange = (_, company) => {
    setValues((current) => ({
      ...current,
      companyId: company?.id || '',
    }));
  };

  const handleSubmit = async (event) => {
    event.preventDefault();
    setTouched({ companyId: true, name: true, email: true, phone: true });

    if (!isFormValid) {
      return;
    }

    const payload = {
      companyId: values.companyId,
      name: values.name.trim(),
      email: values.email.trim(),
      phone: values.phone.trim(),
      role: values.role?.trim() || null,
      lastContactedAt: values.lastContactedAt ? new Date(values.lastContactedAt).toISOString() : null,
    };

    await onSubmit(payload);
  };

  return (
    <Dialog open={open} onClose={isPending ? undefined : onClose} fullWidth maxWidth="sm">
      <DialogTitle>
        {mode === 'create' ? 'Create contact' : 'Edit contact'}
      </DialogTitle>

      <DialogContent sx={{ p: 2.5 }}>

        <Stack component="form" spacing={2} onSubmit={handleSubmit} >
            <TextField
            autoFocus
            required
            label="Name"
            value={values.name}
            onBlur={handleBlur('name')}
            onChange={handleChange('name')}
            error={touched.name && Boolean(errors.name)}
            helperText={touched.name ? errors.name : undefined}
          />

          <Autocomplete
            fullWidth
            options={companyOptions}
            value={selectedCompany}
            loading={companiesQuery.isLoading}
            onBlur={handleBlur('companyId')}
            onChange={handleCompanyChange}
            isOptionEqualToValue={(option, value) => option.id === value.id}
            getOptionLabel={(option) => option?.name || ''}
            noOptionsText={companiesQuery.isLoading ? 'Loading companies...' : 'No companies found'}
            sx={{
              '& .MuiOutlinedInput-root .MuiAutocomplete-input': {
                padding: '0 !important',
              },
            }}
            renderInput={(params) => (
              <TextField
                {...params}
                required
                label="Company"
                error={touched.companyId && Boolean(errors.companyId)}
                helperText={
                  touched.companyId
                    ? errors.companyId
                    : companiesQuery.isError
                      ? 'Failed to load companies.'
                      : undefined
                }
                InputProps={{
                  ...params.InputProps,
                  endAdornment: (
                    <>
                      {companiesQuery.isLoading ? (
                        <CircularProgress color="inherit" size={20} />
                      ) : null}
                      {params.InputProps.endAdornment}
                    </>
                  ),
                }}
              />
            )}
          />



          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2}>
            <TextField
              required
              fullWidth
              label="Email"
              type="email"
              value={values.email}
              onBlur={handleBlur('email')}
              onChange={handleChange('email')}
              error={touched.email && Boolean(errors.email)}
              helperText={touched.email ? errors.email : undefined}
            />
            <TextField
              required
              fullWidth
              label="Phone"
              type="tel"
              placeholder="+00 00000000000"
              value={values.phone}
              onBlur={handleBlur('phone')}
              onChange={handleChange('phone')}
              error={touched.phone && Boolean(errors.phone)}
              helperText={touched.phone ? errors.phone : undefined}
            />
          </Stack>

          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2}>
            <TextField
              fullWidth
              label="Role"
              value={values.role || ''}
              onChange={handleChange('role')}
              placeholder="e.g. Manager, User, Admin"
            />

            <TextField
              fullWidth
              label="Last Contacted At"
              type="datetime-local"
              InputLabelProps={{ shrink: true }}
              value={values.lastContactedAt}
              onChange={handleChange('lastContactedAt')}
            />
          </Stack>

          {/* 创建时间：仅在编辑模式下可见且不可更改 */}
          {mode === 'edit' && initialValues?.createdAt && (
            <TextField
              disabled
              label="Created At"
              value={new Intl.DateTimeFormat('en', {
                dateStyle: 'medium',
                timeStyle: 'short'
              }).format(new Date(initialValues.createdAt))}
            />
          )}

          <button type="submit" hidden />
        </Stack>
      </DialogContent>

      <DialogActions className="crm-dialog-actions">
        <Button onClick={onClose} disabled={isPending}>
          Cancel
        </Button>
        <Button variant="contained" onClick={handleSubmit} disabled={isPending}>
          {mode === 'create' ? 'Create' : 'Save'}
        </Button>
      </DialogActions>
    </Dialog>
  );
}

import {
  Alert,
  Box,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Snackbar,
  Typography,
  Stack,
} from '@mui/material';
import PlusOutlined from '@ant-design/icons/PlusOutlined';
import { useNavigate } from 'react-router-dom';
import { useState } from 'react';

import { isTransportError } from 'api/request';
import { DataTablePagination } from '../../components/Table/Pagination/Pagination';
import { DataTableShell } from '../../components/Table/Shell/Shell';
import { ContactFormDialog } from './ContactForm';
import { ContactTable } from './ContactTable';

import {
  useContactList,
  useCreateContact,
  useDeleteContact,
  useUpdateContact,
} from './contactQueries';

function extractErrorMessage(error, fallbackMessage) {
  return error?.message || fallbackMessage;
}

export default function ContactsPage() {
  const navigate = useNavigate();
  const createContact = useCreateContact();
  const updateContact = useUpdateContact();
  const deleteContact = useDeleteContact();
  const [formState, setFormState] = useState({ open: false, mode: 'create', contact: null });
  const [deleteTarget, setDeleteTarget] = useState(null);
  const [feedback, setFeedback] = useState({ open: false, severity: 'success', message: '' });
  const [searchInput, setSearchInput] = useState('');
  const [listQuery, setListQuery] = useState({
    page: 1,
    pageSize: 10,
  });
  const contactsQuery = useContactList(listQuery);

  const handleFormSubmit = async (payload) => {
    try {
      if (formState.mode === 'create') {
        await createContact.mutateAsync(payload);
        setFeedback({
          open: true,
          severity: 'success',
          message: 'Contact created.',
        });
      } else {
        await updateContact.mutateAsync({
          id: formState.contact.id,
          data: payload,
        });
        setFeedback({
          open: true,
          severity: 'success',
          message: 'Contact updated.',
        });
      }

      setFormState({ open: false, mode: 'create', contact: null });
    } catch (error) {
      // Transport-level failures (network/5xx) are already toasted globally
      // (see App.jsx); only surface business errors here.
      if (!isTransportError(error)) {
        setFeedback({
          open: true,
          severity: 'error',
          message: extractErrorMessage(error, 'Contact request failed.'),
        });
      }
    }
  };

  const handleDelete = async () => {
    if (!deleteTarget) {
      return;
    }

    try {
      await deleteContact.mutateAsync(deleteTarget.id);
      setDeleteTarget(null);
      setFeedback({
        open: true,
        severity: 'success',
        message: 'Contact deleted.',
      });
    } catch (error) {
      if (!isTransportError(error)) {
        setFeedback({
          open: true,
          severity: 'error',
          message: extractErrorMessage(error, 'Delete failed.'),
        });
      }
    }
  };

  const handleSearchSubmit = (event) => {
    event.preventDefault();
    setListQuery((current) => ({
      ...current,
      page: 1,
      ...(searchInput.trim() ? { q: searchInput.trim() } : { q: undefined }),
    }));
  };

  const handleResetFilters = () => {
    setSearchInput('');
    setListQuery({ page: 1, pageSize: listQuery.pageSize });
  };

  const handlePageChange = (page) => {
    setListQuery((current) => ({ ...current, page }));
  };

  const handlePageSizeChange = (pageSize) => {
    setListQuery((current) => ({ ...current, page: 1, pageSize }));
  };

  const contactPage = contactsQuery.data;
  const contactItems = contactPage?.items ?? [];

  return (
    <Stack spacing={3}>
      <DataTableShell
        title="Customers"
        searchValue={searchInput}
        onSearchChange={setSearchInput}
        onSearchSubmit={handleSearchSubmit}
        onReset={handleResetFilters}
        searchPlaceholder="Search by name, email, phone, or role"
        actions={(
          <Button
            variant="contained"
            startIcon={<PlusOutlined />}
            onClick={() =>
              setFormState({
                open: true,
                mode: 'create',
                customer: null,
              })
            }
          >
            Add Contact
          </Button>
        )}
        loading={contactsQuery.isLoading}
        error={
          contactsQuery.isError && !isTransportError(contactsQuery.error)
            ? extractErrorMessage(contactsQuery.error, 'Failed to load contacts.')
            : null
        }
        isEmpty={!contactsQuery.isLoading && !contactsQuery.isError && contactItems.length === 0}
        emptyTitle="No matching contacts"
        emptyDescription="Try broadening the search or clearing the current filters."
        pagination={
          contactPage && contactPage.total > 0 ? (
            <Box sx={{ display: 'flex', width: '100%', justifyContent: 'center' }}>
              <DataTablePagination
                page={contactPage.page}
                pageSize={contactPage.pageSize}
                total={contactPage.total}
                totalPages={contactPage.totalPages}
                onPageChange={handlePageChange}
                onPageSizeChange={handlePageSizeChange}
              />
            </Box>
          ) : null
        }
      >
        <ContactTable
          contacts={contactItems}
          onDelete={setDeleteTarget}
          onEdit={(contact) =>
            setFormState({
              open: true,
              mode: 'edit',
              contact,
            })
          }
          onView={(contact) => navigate(`/contacts/${contact.id}`)}
        />
      </DataTableShell>

      <ContactFormDialog
        open={formState.open}
        mode={formState.mode}
        initialValues={formState.contact}
        isPending={createContact.isPending || updateContact.isPending}
        onClose={() => setFormState({ open: false, mode: 'create', contact: null })}
        onSubmit={handleFormSubmit}
      />

      <Dialog open={Boolean(deleteTarget)} onClose={() => setDeleteTarget(null)}>
        <DialogTitle>Delete contact</DialogTitle>
        <DialogContent>
          <Typography>
             Delete {deleteTarget?.name}? This action cannot be undone.
          </Typography>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setDeleteTarget(null)}>Cancel</Button>
          <Button color="error" variant="contained" onClick={handleDelete}>
            Delete
          </Button>
        </DialogActions>
      </Dialog>

      <Snackbar
        open={feedback.open}
        autoHideDuration={3200}
        onClose={() => setFeedback((current) => ({ ...current, open: false }))}
      >
        <Alert
          onClose={() => setFeedback((current) => ({ ...current, open: false }))}
          severity={feedback.severity}
          variant="filled"
        >
          {feedback.message}
        </Alert>
      </Snackbar>
    </Stack>
  );
}

import {
  Alert,
  Box,
  Button,
  MenuItem,
  Snackbar,
  Stack,
  TextField,
} from '@mui/material';
import PlusOutlined from '@ant-design/icons/PlusOutlined';
import { useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';

import { isTransportError } from 'api/request';
import { DataTablePagination } from '../../components/Table/Pagination/Pagination';
import { DataTableShell } from '../../components/Table/Shell/Shell';
import { useCompanyList } from '../companies/companyQueries';
import { DealFormDialog } from './DealForm';
import { useCreateDeal, useDealList, useUpdateDeal } from './dealQueries';
import { DealTable } from './DealTable';

function extractErrorMessage(error, fallbackMessage) {
  return error?.message || fallbackMessage;
}

export default function DealsPage() {
  const navigate = useNavigate();
  const createDeal = useCreateDeal();
  const updateDeal = useUpdateDeal();

  const [formState, setFormState] = useState({
    open: false,
    mode: 'create',
    deal: null,
  });
  const [feedback, setFeedback] = useState({
    open: false,
    severity: 'success',
    message: '',
  });
  const [stageInput, setStageInput] = useState('');
  const [companyInput, setCompanyInput] = useState('');
  const [listQuery, setListQuery] = useState({ page: 1, pageSize: 10 });

  const dealsQuery = useDealList(listQuery);
  const companiesQuery = useCompanyList({ page: 1, pageSize: 100 });
  const companyOptions = useMemo(
    () => companiesQuery.data?.items ?? [],
    [companiesQuery.data?.items],
  );

  const companyNameById = useMemo(
    () =>
      Object.fromEntries(
        companyOptions.map((company) => [company.id, company.name]),
      ),
    [companyOptions],
  );

  const handleSearchSubmit = (event) => {
    event.preventDefault();
    setListQuery((current) => ({
      ...current,
      page: 1,
      stage: stageInput.trim() || undefined,
      companyId: companyInput || undefined,
    }));
  };

  const handleResetFilters = () => {
    setStageInput('');
    setCompanyInput('');
    setListQuery((current) => ({ page: 1, pageSize: current.pageSize }));
  };

  const handleFormSubmit = async (payload) => {
    try {
      if (formState.mode === 'create') {
        await createDeal.mutateAsync(payload);
        setFeedback({
          open: true,
          severity: 'success',
          message: 'Deal created.',
        });
      } else {
        await updateDeal.mutateAsync({
          id: formState.deal.id,
          data: payload,
        });
        setFeedback({
          open: true,
          severity: 'success',
          message: 'Deal updated.',
        });
      }

      setFormState({ open: false, mode: 'create', deal: null });
    } catch (error) {
      if (!isTransportError(error)) {
        setFeedback({
          open: true,
          severity: 'error',
          message: extractErrorMessage(error, 'Deal request failed.'),
        });
      }
    }
  };

  const dealPage = dealsQuery.data;
  const dealItems = dealPage?.items ?? [];

  return (
    <Stack spacing={3}>
      <DataTableShell
        title="Deals"
        searchValue={stageInput}
        onSearchChange={setStageInput}
        onSearchSubmit={handleSearchSubmit}
        onReset={handleResetFilters}
        searchPlaceholder="Filter by stage (exact match)"
        filters={(
          <TextField
            select
            size="small"
            label="Company"
            value={companyInput}
            onChange={(event) => setCompanyInput(event.target.value)}
            sx={{ minWidth: '14rem' }}
          >
            <MenuItem value="">All companies</MenuItem>
            {companyOptions.map((company) => (
              <MenuItem key={company.id} value={company.id}>
                {company.name}
              </MenuItem>
            ))}
          </TextField>
        )}
        actions={(
          <Button
            variant="contained"
            startIcon={<PlusOutlined />}
            onClick={() =>
              setFormState({
                open: true,
                mode: 'create',
                deal: null,
              })
            }
          >
            Add Deal
          </Button>
        )}
        loading={dealsQuery.isLoading}
        error={
          dealsQuery.isError && !isTransportError(dealsQuery.error)
            ? extractErrorMessage(dealsQuery.error, 'Failed to load deals.')
            : null
        }
        isEmpty={!dealsQuery.isLoading && !dealsQuery.isError && dealItems.length === 0}
        emptyTitle="No matching deals"
        emptyDescription="Try adjusting stage/company filters or clear filters."
        pagination={
          dealPage && dealPage.total > 0 ? (
            <Box sx={{ display: 'flex', width: '100%', justifyContent: 'center' }}>
              <DataTablePagination
                page={dealPage.page}
                pageSize={dealPage.pageSize}
                total={dealPage.total}
                totalPages={dealPage.totalPages}
                onPageChange={(page) =>
                  setListQuery((current) => ({
                    ...current,
                    page,
                  }))
                }
                onPageSizeChange={(pageSize) =>
                  setListQuery((current) => ({
                    ...current,
                    page: 1,
                    pageSize,
                  }))
                }
              />
            </Box>
          ) : null
        }
      >
        <DealTable
          deals={dealItems}
          companyNameById={companyNameById}
          onView={(deal) => navigate(`/deals/${deal.id}`)}
          onEdit={(deal) =>
            setFormState({
              open: true,
              mode: 'edit',
              deal,
            })
          }
        />
      </DataTableShell>

      <DealFormDialog
        open={formState.open}
        mode={formState.mode}
        initialValues={formState.deal}
        isPending={createDeal.isPending || updateDeal.isPending}
        onClose={() => setFormState({ open: false, mode: 'create', deal: null })}
        onSubmit={handleFormSubmit}
      />

      <Snackbar
        open={feedback.open}
        autoHideDuration={3200}
        onClose={() => setFeedback((current) => ({ ...current, open: false }))}
      >
        <Alert
          onClose={() => setFeedback((current) => ({ ...current, open: false }))}
          severity={feedback.severity}
          variant="filled"
        >
          {feedback.message}
        </Alert>
      </Snackbar>
    </Stack>
  );
}

