import { Injectable } from '@nestjs/common';
import { DataSource } from 'typeorm';
import { BaseRepository } from '../../core/database/base.repository';
import { ContactCompanyLinkEntity } from './contact-company-link.entity';

export type ContactCompanySummary = {
  id: string;
  name: string;
  isPrimary: boolean;
};

@Injectable()
export class ContactCompanyLinkRepository extends BaseRepository<ContactCompanyLinkEntity> {
  constructor(dataSource: DataSource) {
    super(ContactCompanyLinkEntity, dataSource.createEntityManager());
  }

  async findCompanySummariesByContactIds(contactIds: string[]) {
    if (contactIds.length === 0) {
      return new Map<string, ContactCompanySummary[]>();
    }

    const rows = await this.createQueryBuilder('link')
      .innerJoin('companies', 'company', 'company.id = link.companyId')
      .select('link.contactId', 'contactId')
      .addSelect('company.id', 'companyId')
      .addSelect('company.name', 'companyName')
      .addSelect('link.isPrimary', 'isPrimary')
      .where('link.contactId IN (:...contactIds)', { contactIds })
      .orderBy('link.isPrimary', 'DESC')
      .addOrderBy('company.name', 'ASC')
      .getRawMany<{
        contactId: string;
        companyId: string;
        companyName: string;
        isPrimary: boolean;
      }>();

    const map = new Map<string, ContactCompanySummary[]>();

    for (const row of rows) {
      const existing = map.get(row.contactId) ?? [];
      existing.push({
        id: row.companyId,
        name: row.companyName,
        isPrimary: row.isPrimary,
      });
      map.set(row.contactId, existing);
    }

    return map;
  }

  async findLinksByContactId(contactId: string) {
    return this.find({
      where: { contactId },
      order: {
        isPrimary: 'DESC',
        companyId: 'ASC',
      },
    });
  }
}
