  Industry.TECHNOLOGY,
  Industry.FINANCE,
  Industry.MANUFACTURING,
  Industry.RETAIL,
  Industry.OTHER,
] as const;
const DEAL_STAGES = [
  'lead',
  'qualified',
  'proposal',
  'negotiation',
  'closed-won',
] as const;

type DemoCompanyRecord = {
  company: CompanyEntity;
  contactIds: string[];
};

const saveContactWithLinks = async (
  context: SeedContext,
  input: ReturnType<typeof buildContact>,
) => {
  const contactRepository = context.dataSource.getRepository(ContactEntity);
  const linkRepository = context.dataSource.getRepository(ContactCompanyLinkEntity);

  const savedContact = await contactRepository.save(
    contactRepository.create(input.contact),
  );

  await linkRepository.save(
    input.companyLinks.map((companyLink) =>
      linkRepository.create({
        contactId: savedContact.id,
        companyId: companyLink.companyId,
        isPrimary: companyLink.isPrimary,
      }),
    ),
  );

  return savedContact;
};

const saveDealWithLinks = async (
  context: SeedContext,
  input: ReturnType<typeof buildDeal>,
) => {
  const dealRepository = context.dataSource.getRepository(DealEntity);
  const linkRepository = context.dataSource.getRepository(DealContactLinkEntity);

  const savedDeal = await dealRepository.save(dealRepository.create(input.deal));

  if (input.contactLinks.length > 0) {
    await linkRepository.save(
      input.contactLinks.map((contactLink) =>
        linkRepository.create({
          dealId: savedDeal.id,
          contactId: contactLink.contactId,
          role: contactLink.role,
        }),
      ),
    );
  }

  return savedDeal;
};

const createDemoCompanies = async (context: SeedContext) => {
  const companyRepository = context.dataSource.getRepository(CompanyEntity);
  let contactsCreated = 0;
  const companyRecords: DemoCompanyRecord[] = [];

  await cleanupCompaniesByPrefixes(context, [DEMO_PREFIX]);

  for (let companyIndex = 0; companyIndex < 10; companyIndex += 1) {
    const companyName = "'`${DEMO_PREFIX} ${String(companyIndex + 1).padStart(2, '"'0')}"'`;
    const company = await companyRepository.save(
      companyRepository.create(
        buildCompany({
          name: companyName,
          status: STATUSES[companyIndex % STATUSES.length],
          industry: INDUSTRIES[companyIndex % INDUSTRIES.length],
          lastContactedAt: distributeRecentDate(context.now, companyIndex, 10),
          email: `demo-company-${companyIndex + 1}@baseline.local`,
        }),
      ),
    );

    const contactsForCompany = 2 + (companyIndex % 4);
    const contactIds: string[] = [];

    for (
      let contactIndex = 0;
      contactIndex < contactsForCompany;
      contactIndex += 1
    ) {
      contactsCreated += 1;

      const contact = await saveContactWithLinks(
        context,
        buildContact({
          companies: [{ companyId: company.id, isPrimary: true }],
