  if (companyRecords.length >= 2 && companyRecords[0].contactIds.length > 0) {
    const linkRepository = context.dataSource.getRepository(ContactCompanyLinkEntity);

    await linkRepository.save(
      linkRepository.create({
        contactId: companyRecords[0].contactIds[0],
        companyId: companyRecords[1].company.id,
        isPrimary: false,
      }),
    );
  }

  return {
    contactsCreated,
    companyRecords,
  };
};

const createDemoDeals = async (
  context: SeedContext,
