/bin/bash -lc "cat > backend/src/modules/contact/contact.service.spec.ts <<'EOF'
import { HttpStatus } from '@nestjs/common';
import { BUSINESS_ERROR_CODES } from '../../common/errors/error-codes';
import { AppException } from '../../common/errors/app-exception';
import { ContactService } from './contact.service';

describe('ContactService', () => {
  const buildService = () => {
    const transaction = jest
      .fn()
      .mockImplementation(async (callback: (manager: unknown) => unknown) =>
        callback({
          getRepository: jest.fn().mockReturnValue({
            create: jest.fn(),
            save: jest.fn(),
            delete: jest.fn(),
            merge: jest.fn(),
          }),
        }),
      );

    const contactRepository = {
      create: jest.fn(),
      save: jest.fn(),
      findWithFilter: jest.fn(),
      findOne: jest.fn(),
      merge: jest.fn(),
      softDelete: jest.fn(),
      manager: {
        transaction,
      },
    };

    const contactCompanyLinkRepository = {
      findCompanySummariesByContactIds: jest.fn(),
      findLinksByContactId: jest.fn(),
    };

    const companyService = {
      getCompanyById: jest.fn(),
    };

    return {
      service: new ContactService(
        contactRepository as never,
        contactCompanyLinkRepository as never,
        companyService as never,
      ),
      contactRepository,
      contactCompanyLinkRepository,
      companyService,
    };
  };

  it('returns NOT_FOUND when the contact is missing', async () => {
    const { service, contactRepository } = buildService();
    contactRepository.findOne.mockResolvedValue(null);

    await expect(service.getContactById('missing-contact')).rejects.toMatchObject(
      {
        status: HttpStatus.NOT_FOUND,
        response: {
          code: BUSINESS_ERROR_CODES.NOT_FOUND,
          details: {
            resource: 'Contact',
            id: 'missing-contact',
          },
        },
      },
    );
  });

  it('fails contact creation when a linked company does not exist', async () => {
    const { service, companyService, contactRepository } = buildService();

    companyService.getCompanyById.mockRejectedValue(
      new AppException({
        statusCode: HttpStatus.NOT_FOUND,
        code: BUSINESS_ERROR_CODES.NOT_FOUND,
        message: 'Company not found',
      }),
    );

    await expect(
      service.createContact({
        companies: [{ id: 'company-1', isPrimary: true }],
        name: 'Contact One',
        email: 'contact-one@test.local',
        phone: '+12025550101',
      }),
    ).rejects.toMatchObject({
      status: HttpStatus.NOT_FOUND,
      response: {
        code: BUSINESS_ERROR_CODES.NOT_FOUND,
        details: {
          resource: 'Company',
          id: 'company-1',
        },
      },
    });

    expect(contactRepository.manager.transaction).not.toHaveBeenCalled();
  });

  it('returns INVALID_LINK_STATE for invalid primary-link replacement', async () => {
    const {
      service,
      contactRepository,
      contactCompanyLinkRepository,
      companyService,
    } = buildService();

    contactRepository.findOne.mockResolvedValue({
      id: 'contact-1',
      name: 'Contact One',
    });
    contactCompanyLinkRepository.findLinksByContactId.mockResolvedValue([
      {
        contactId: 'contact-1',
        companyId: 'company-a',
        isPrimary: true,
      },
      {
        contactId: 'contact-1',
        companyId: 'company-b',
        isPrimary: false,
      },
    ]);
    companyService.getCompanyById.mockResolvedValue({ id: 'company-c' });

    await expect(
      service.updateContact('contact-1', {
        companies: [{ id: 'company-c', isPrimary: true }],
      }),
    ).rejects.toMatchObject({
      status: HttpStatus.CONFLICT,
      response: {
        code: BUSINESS_ERROR_CODES.INVALID_LINK_STATE,
      },
    });
  });
});
EOF"

