import { DataSource } from 'typeorm';
import {
  closeTestDataSource,
  getTestDataSource,
  listConstraintNames,
  listIndexNames,
} from './setup/test-database';

jest.setTimeout(30000);

describe('Database migrations (e2e)', () => {
  let dataSource: DataSource;

  beforeAll(async () => {
    dataSource = await getTestDataSource();
  });

  afterAll(async () => {
    await closeTestDataSource();
  });

  beforeEach(async () => {
    await dataSource.query('DROP SCHEMA IF EXISTS public CASCADE');
    await dataSource.query('CREATE SCHEMA public');
    await dataSource.query('CREATE EXTENSION IF NOT EXISTS \"uuid-ossp\"');
    await dataSource.query('CREATE EXTENSION IF NOT EXISTS \"pgcrypto\"');
    await dataSource.synchronize();
  });

  it('runs migrations and applies link-table schema constraints', async () => {
    await dataSource.runMigrations();

    await expect(listConstraintNames(dataSource, 'deals')).resolves.toEqual(
      expect.arrayContaining([
        'fk_deals_company_id',
        'fk_deals_primary_contact_id',
        'chk_deals_value_non_negative',
      ]),
    );

    await expect(
      listConstraintNames(dataSource, 'contact_company_links'),
    ).resolves.toEqual(
      expect.arrayContaining([
        'fk_contact_company_links_company_id',
        'fk_contact_company_links_contact_id',
        'pk_contact_company_links',
      ]),
    );

    await expect(
      listConstraintNames(dataSource, 'deal_contact_links'),
    ).resolves.toEqual(
      expect.arrayContaining([
        'fk_deal_contact_links_contact_id',
        'fk_deal_contact_links_deal_id',
        'pk_deal_contact_links',
      ]),
    );

    await expect(listIndexNames(dataSource, 'deals')).resolves.toEqual(
      expect.arrayContaining([
        'idx_deals_company_id',
        'idx_deals_primary_contact_id',
        'idx_deals_stage',
      ]),
    );

    await expect(
      listIndexNames(dataSource, 'contact_company_links'),
    ).resolves.toEqual(
      expect.arrayContaining([
        'idx_contact_company_links_company_id',
        'idx_contact_company_links_contact_id',
        'ux_contact_company_links_primary_per_contact',
      ]),
    );

    await expect(
      listIndexNames(dataSource, 'deal_contact_links'),
    ).resolves.toEqual(
      expect.arrayContaining(['idx_deal_contact_links_contact_id']),
    );

    await expect(hasColumn('contacts', 'companyId')).resolves.toBe(false);
    await expect(hasColumn('deals', 'contactId')).resolves.toBe(false);
    await expect(hasColumn('deals', 'primaryContactId')).resolves.toBe(true);
  });

  it('rolls back migrations to restore legacy columns', async () => {
    await dataSource.runMigrations();
    await dataSource.undoLastMigration();
    await dataSource.undoLastMigration();
    await dataSource.undoLastMigration();

    await expect(hasTable('contact_company_links')).resolves.toBe(false);
    await expect(hasTable('deal_contact_links')).resolves.toBe(false);
    await expect(hasColumn('contacts', 'companyId')).resolves.toBe(true);
    await expect(hasColumn('deals', 'contactId')).resolves.toBe(true);
    await expect(hasColumn('deals', 'primaryContactId')).resolves.toBe(false);
  });

  it('can rerun migrations after rollback', async () => {
    await dataSource.runMigrations();
    await dataSource.undoLastMigration();
    await dataSource.undoLastMigration();
    await dataSource.undoLastMigration();
    await dataSource.runMigrations();

    await expect(hasTable('contact_company_links')).resolves.toBe(true);
    await expect(hasTable('deal_contact_links')).resolves.toBe(true);
    await expect(hasColumn('contacts', 'companyId')).resolves.toBe(false);
    await expect(hasColumn('deals', 'contactId')).resolves.toBe(false);
  });

  it('prevents orphan links and orphan company references', async () => {
    await dataSource.runMigrations();

    await dataSource.query(
      "'`
        INSERT INTO "contacts" ("id", "name", "email", "phone", "role", "createdAt", "updatedAt")
        VALUES (gen_random_uuid(), '"'Orphan Link Contact', 'orphan-link@test.local', '0200-7777', 'User', NOW(), NOW())
      "'`,
    );

    const [{ id: contactId }] = await dataSource.query(
      `
        SELECT id
        FROM "contacts"
        WHERE name = '"'Orphan Link Contact'
      "'`,
    );

    await expect(
      dataSource.query(
        `
          INSERT INTO "contact_company_links" ("contactId", "companyId", "isPrimary", "createdAt", "updatedAt")
          VALUES ($1, $2, true, NOW(), NOW())
        `,
        [contactId, '"'7f4f54f7-cd3c-4ef2-b22d-8f1d68d9f1aa'],
      ),
    ).rejects.toThrow(/fk_contact_company_links_company_id/i);

    await expect(
      dataSource.query(
        "'`
          INSERT INTO "deals" ("id", "name", "value", "stage", "companyId", "primaryContactId", "expectedCloseDate", "createdAt", "updatedAt")
          VALUES (gen_random_uuid(), '"'Orphan Deal', 1000, 'lead', "'$1, NULL, NULL, NOW(), NOW())
        `,
        ['"'7f4f54f7-cd3c-4ef2-b22d-8f1d68d9f1aa'],
      ),
    ).rejects.toThrow(/fk_deals_company_id/i);
  });

  it('prevents negative deal values at the database layer', async () => {
    await dataSource.runMigrations();

    await dataSource.query(
      "'`
        INSERT INTO "companies" ("id", "name", "status", "createdAt", "updatedAt")
        VALUES (gen_random_uuid(), '"'Constraint Company', '1', NOW(), NOW())
      "'`,
    );

    const [{ id: companyId }] = await dataSource.query(
      `
        SELECT id
        FROM "companies"
        WHERE name = '"'Constraint Company'
      "'`,
    );

    await expect(
      dataSource.query(
        `
          INSERT INTO "deals" ("id", "name", "value", "stage", "companyId", "primaryContactId", "expectedCloseDate", "createdAt", "updatedAt")
          VALUES (gen_random_uuid(), '"'Negative Deal', -1, 'lead', "'$1, NULL, NULL, NOW(), NOW())
        `,
        [companyId],
      ),
    ).rejects.toThrow(/chk_deals_value_non_negative/i);
  });

  async function hasColumn(tableName: string, columnName: string) {
    const rows = await dataSource.query(
      `
        SELECT column_name
        FROM information_schema.columns
        WHERE table_schema = '"'public'
          AND table_name = "'$1
          AND column_name = $2
      `,
      [tableName, columnName],
    );

    return rows.length > 0;
  }

  async function hasTable(tableName: string) {
    const rows = await dataSource.query(
      `
        SELECT table_name
        FROM information_schema.tables
        WHERE table_schema = '"'public'
          AND table_name = "'$1
      `,
      [tableName],
    );

    return rows.length > 0;
  }
});
