      `
        SELECT column_name
        FROM information_schema.columns
        WHERE table_schema = '"'public'
          AND table_name = "'$1
          AND column_name = $2
      `,
      [tableName, columnName],
    );

    return rows.length > 0;
  }

  async function hasTable(tableName: string) {
    const rows = await dataSource.query(
      `
        SELECT table_name
        FROM information_schema.tables
        WHERE table_schema = '"'public'
          AND table_name = "'$1
      `,
      [tableName],
    );

    return rows.length > 0;
  }
});
