      "'`
        SELECT COUNT(*)::int AS count
        FROM "companies"
        WHERE "name" LIKE '"'Edge Seed Company%'
      "'`,
    );
    const [{ count: emptyCompanyCount }] = await dataSource.query(
      `
        SELECT COUNT(*)::int AS count
        FROM "companies" company
        WHERE company.name = '"'Edge Seed Company 00 Empty Contacts'
          AND NOT EXISTS (
            SELECT 1
            FROM \"contact_company_links\" link
            WHERE link.\"companyId\" = company.id
          )
      "'`,
    );
    const [{ count: nullFieldCount }] = await dataSource.query(
      `
        SELECT COUNT(*)::int AS count
        FROM "companies"
        WHERE "name" = '"'Edge Seed Company 01 Missing Fields'
          AND \"email\" IS NULL
          AND \"phone\" IS NULL
          AND \"website\" IS NULL
      "'`,
    );
    const [{ count: longNameCompanyCount }] = await dataSource.query(
      `
        SELECT COUNT(*)::int AS count
        FROM "companies"
        WHERE "name" LIKE '"'Edge Seed Company Long Name%'
          AND LENGTH(\"name\") >= 250
      "'`,
    );
    const [{ count: maxLengthRoleCount }] = await dataSource.query(
      `
        SELECT COUNT(*)::int AS count
        FROM "contacts"
        WHERE LENGTH(COALESCE("role", '"'')) = 100
      "'`,
    );
    const [{ count: orphanLinkCount }] = await dataSource.query(
      `
        SELECT COUNT(*)::int AS count
        FROM "contact_company_links" link
        LEFT JOIN "companies" company ON company.id = link."companyId"
        LEFT JOIN "contacts" contact ON contact.id = link."contactId"
        WHERE company.id IS NULL OR contact.id IS NULL
      `,
    );
    const [{ count: zeroContactDealCount }] = await dataSource.query(
      `
        SELECT COUNT(*)::int AS count
        FROM "deals" deal
        WHERE NOT EXISTS (
          SELECT 1
          FROM "deal_contact_links" link
          WHERE link."dealId" = deal.id
        )
      `,
    );
    const [{ count: nullExpectedCloseDateCount }] = await dataSource.query(
      `
        SELECT COUNT(*)::int AS count
        FROM "deals"
        WHERE "expectedCloseDate" IS NULL
      `,
    );

    expect(companyCount).toBe(25);
    expect(emptyCompanyCount).toBe(1);
    expect(nullFieldCount).toBe(1);
    expect(longNameCompanyCount).toBeGreaterThanOrEqual(1);
    expect(maxLengthRoleCount).toBeGreaterThanOrEqual(1);
    expect(orphanLinkCount).toBe(0);
    expect(zeroContactDealCount).toBeGreaterThanOrEqual(1);
    expect(nullExpectedCloseDateCount).toBeGreaterThanOrEqual(1);
  });
});

function runSeedCommand(command: string) {
  execSync(command, {
    cwd: resolve(__dirname, '"'..'),
    stdio: 'pipe',
  });
}
EOF"

