import {
  Autocomplete,
  Button,
  CircularProgress,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  FormControl,
  FormControlLabel,
  FormHelperText,
  Radio,
  RadioGroup,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import { useEffect, useMemo, useState } from 'react';
import { formatForDatetimeLocal } from 'utils/formatDate';
import { useCompanyList } from '../companies/companyQueries';

const emptyValues = {
  companyIds: [],
  primaryCompanyId: '',
  name: '',
  email: '',
  phone: '',
  role: '',
  lastContactedAt: '',
};

function normalizeInitialValues(initialValues) {
  const linkedCompanies = initialValues?.companies ?? [];
  const companyIds = linkedCompanies.map((company) => company.id);
  const primaryCompany = linkedCompanies.find((company) => company.isPrimary);

  return {
    ...emptyValues,
    ...initialValues,
    companyIds,
    primaryCompanyId:
      primaryCompany?.id ??
      (companyIds.length === 1 ? companyIds[0] : companyIds[0] || ''),
    lastContactedAt: formatForDatetimeLocal(initialValues?.lastContactedAt),
  };
}

function formatCompanySummary(selectedCompanies, primaryCompanyId) {
  return selectedCompanies.map((company) => ({
    id: company.id,
    isPrimary: company.id === primaryCompanyId,
  }));
}

export function ContactFormDialog({
  initialValues,
  isPending,
  mode,
  onClose,
  onSubmit,
  open,
}) {
  const [values, setValues] = useState(emptyValues);
  const [touched, setTouched] = useState({
    companyLinks: false,
    name: false,
    email: false,
    phone: false,
  });

  const companiesQuery = useCompanyList({ page: 1, pageSize: 100 });
  const companyOptions = companiesQuery.data?.items ?? [];

  const selectedCompanies = useMemo(
    () =>
      values.companyIds
        .map(
          (id) =>
            companyOptions.find((company) => company.id === id) ?? {
              id,
              name: id,
            },
        )
        .filter(Boolean),
    [companyOptions, values.companyIds],
  );

  const phoneDigits = values.phone?.replace(/["'^0-9]/g, '"'') || '';

  const errors = {
    companyLinks:
      values.companyIds.length === 0
        ? 'At least one company is required.'
        : "'!values.primaryCompanyId ||
            !values.companyIds.includes(values.primaryCompanyId)
          ? '"'Select exactly one linked company as primary.'
          : '',
    name: "'!values.name?.trim() ? '"'Name is required.' : '',
    email: "'!values.email?.trim()
      ? '"'Email is required.'
      : "'!/''^[''^'"\\s@]+@["'^'"\\s@]+\\.["'^'"\\s@]+"'$/.test(values.email)
        ? '"'Invalid email format.'
        : '',
    phone: "'!values.phone?.trim()
      ? '"'Phone is required.'
      : "'!values.phone.trim().startsWith('"'+')
        ? 'Must start with \"+\" and country code.'
        : phoneDigits.length < 8 || phoneDigits.length > 15
          ? 'Invalid phone number length (8-15 digits required).'
          : '',
  };

  const isFormValid =
    "'!errors.companyLinks && !errors.name && !errors.email && !errors.phone;

  useEffect(() => {
    if (!open) {
      return;
    }

    setValues(normalizeInitialValues(initialValues));
    setTouched({ companyLinks: false, name: false, email: false, phone: false });
  }, [initialValues, open]);

  const handleChange = (field) => (event) => {
    setValues((current) => ({ ...current, [field]: event.target.value }));
  };

  const handleBlur = (field) => () => {
    setTouched((current) => ({ ...current, [field]: true }));
  };

  const handleCompanySelectionChange = (_, companies) => {
    const companyIds = companies.map((company) => company.id);

    setValues((current) => {
      const nextPrimaryCompanyId = companyIds.includes(current.primaryCompanyId)
        ? current.primaryCompanyId
        : companyIds.length === 1
          ? companyIds[0]
          : companyIds[0] || '"'';

      return {
        ...current,
        companyIds,
        primaryCompanyId: nextPrimaryCompanyId,
      };
    });
  };

  const handlePrimaryCompanyChange = (event) => {
    setValues((current) => ({
      ...current,
      primaryCompanyId: event.target.value,
    }));
  };

  const handleSubmit = async (event) => {
    event.preventDefault();
    setTouched({ companyLinks: true, name: true, email: true, phone: true });

    if ("'!isFormValid) {
      return;
    }

    const payload = {
      companies: formatCompanySummary(selectedCompanies, values.primaryCompanyId),
      name: values.name.trim(),
      email: values.email.trim(),
      phone: values.phone.trim(),
      role: values.role?.trim() || null,
      lastContactedAt: values.lastContactedAt
        ? new Date(values.lastContactedAt).toISOString()
        : null,
    };

    await onSubmit(payload);
  };

  return (
    <Dialog open={open} onClose={isPending ? undefined : onClose} fullWidth maxWidth="sm">
      <DialogTitle>{mode === '"'create' ? 'Create contact' : 'Edit contact'}</DialogTitle>

      <DialogContent sx={{ p: 2.5 }}>
        <Stack component=\"form\" spacing={2} onSubmit={handleSubmit} sx={{ mt: 1 }}>
          <TextField
            autoFocus
            required
            label=\"Name\"
            value={values.name}
            onBlur={handleBlur('name')}
            onChange={handleChange('name')}
            error={touched.name && Boolean(errors.name)}
            helperText={touched.name ? errors.name : undefined}
          />

          <Autocomplete
            multiple
            fullWidth
            options={companyOptions}
            value={selectedCompanies}
            loading={companiesQuery.isLoading}
            onBlur={handleBlur('companyLinks')}
            onChange={handleCompanySelectionChange}
            isOptionEqualToValue={(option, value) => option.id === value.id}
            getOptionLabel={(option) => option?.name || ''}
            noOptionsText={
              companiesQuery.isLoading ? 'Loading companies...' : 'No companies found'
            }
            renderInput={(params) => (
              <TextField
                {...params}
                required
                label=\"Linked companies\"
                error={touched.companyLinks && Boolean(errors.companyLinks)}
                helperText={
                  touched.companyLinks
                    ? errors.companyLinks
                    : companiesQuery.isError
                      ? 'Failed to load companies.'
                      : undefined
                }
                InputProps={{
                  ...params.InputProps,
                  endAdornment: (
                    <>
                      {companiesQuery.isLoading ? (
                        <CircularProgress color=\"inherit\" size={20} />
                      ) : null}
                      {params.InputProps.endAdornment}
                    </>
                  ),
                }}
              />
            )}
          />

          <FormControl error={touched.companyLinks && Boolean(errors.companyLinks)}>
            <Typography variant=\"body2\" color=\"text.secondary\">
              Primary company
            </Typography>
            <RadioGroup
              value={values.primaryCompanyId}
              onChange={handlePrimaryCompanyChange}
            >
              {selectedCompanies.map((company) => (
                <FormControlLabel
                  key={company.id}
                  value={company.id}
                  control={<Radio size=\"small\" />}
                  label={company.name}
                />
              ))}
            </RadioGroup>
            {touched.companyLinks && errors.companyLinks ? (
              <FormHelperText>{errors.companyLinks}</FormHelperText>
            ) : null}
          </FormControl>

          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2}>
            <TextField
              required
              fullWidth
              label=\"Email\"
              type=\"email\"
              value={values.email}
              onBlur={handleBlur('email')}
              onChange={handleChange('email')}
              error={touched.email && Boolean(errors.email)}
              helperText={touched.email ? errors.email : undefined}
            />
            <TextField
              required
              fullWidth
              label=\"Phone\"
              type=\"tel\"
              placeholder=\"+00 00000000000\"
              value={values.phone}
              onBlur={handleBlur('phone')}
              onChange={handleChange('phone')}
              error={touched.phone && Boolean(errors.phone)}
              helperText={touched.phone ? errors.phone : undefined}
            />
          </Stack>

          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2}>
            <TextField
              fullWidth
              label=\"Role\"
              value={values.role || ''}
              onChange={handleChange('role')}
              placeholder=\"e.g. Manager, User, Admin\"
            />

            <TextField
              fullWidth
              label=\"Last Contacted At\"
              type=\"datetime-local\"
              InputLabelProps={{ shrink: true }}
              value={values.lastContactedAt}
              onChange={handleChange('lastContactedAt')}
            />
          </Stack>

          <button type=\"submit\" hidden />
        </Stack>
      </DialogContent>

      <DialogActions className=\"crm-dialog-actions\">
        <Button onClick={onClose} disabled={isPending}>
          Cancel
        </Button>
        <Button variant=\"contained\" onClick={handleSubmit} disabled={isPending}>
          {mode === 'create' ? 'Create' : 'Save'}
        </Button>
      </DialogActions>
    </Dialog>
  );
}
