        getOptionLabel={(option) => option?.name || ''}
        noOptionsText={
          values.companyId
            ? contactsQuery.isLoading
              ? 'Loading contacts...'
              : 'No contacts available for this company'
            : 'Select a company first'
        }
        renderInput={(params) => (
          <TextField
            {...params}
            label=\"Linked contacts\"
            helperText={
